import 'package:flutter/material.dart';
import '../../data/app_store.dart';
class JournalPage extends StatefulWidget{final AppStore store;const JournalPage({super.key,required this.store});@override State<JournalPage>createState()=>_S();}
class _S extends State<JournalPage>{final c=TextEditingController();final q1='Вы можете вспомнить моменты, которые вызывают у Вас чувство радости, внутреннего спокойствия, счастья?';final q2='Что делает Вас счастливым?';Future<void>save()async{if(c.text.trim().isEmpty)return;widget.store.data['journal'].add({'id':'j_'+DateTime.now().microsecondsSinceEpoch.toString(),'text':c.text.trim(),'createdAt':DateTime.now().toIso8601String(),'wheelIds':[]});await widget.store.save();c.clear();setState((){});}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Дневник')),body:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(q1,style:const TextStyle(fontSize:17,fontWeight:FontWeight.w600)),const SizedBox(height:8),TextField(controller:c,maxLines:6,decoration:InputDecoration(hintText:q2,border:const OutlineInputBorder())),const SizedBox(height:10),FilledButton(onPressed:save,child:const Text('Сохранить запись')),Expanded(child:ListView(children:[...((widget.store.data['journal'] as List?)??[]).reversed.map((e)=>Card(child:ListTile(title:Text(e['text']),subtitle:Text(e['createdAt']))))]))]));}
